CREATE OR REPLACE PROCEDURE WMS_DW.P_LOAD_LABOR(p_site IN NUMBER, p_day IN DATE) IS
  v_rows NUMBER := 0;
BEGIN
  DELETE FROM WMS_DW.FACT_LABOR_ACTIVITY WHERE site_key = p_site AND work_date = TRUNC(p_day);
  INSERT INTO WMS_DW.FACT_LABOR_ACTIVITY (site_key, work_date, direct_hours, load_ts)
  SELECT site_key, TRUNC(task_start), SUM(NVL(duration_min,0))/60, SYSDATE
  FROM WMS_DW.FACT_WAREHOUSE_TASK WHERE site_key = p_site AND TRUNC(task_start) = TRUNC(p_day)
  GROUP BY site_key, TRUNC(task_start);
  v_rows := SQL%ROWCOUNT;
  DBMS_OUTPUT.PUT_LINE('rows ' || v_rows);
  COMMIT;
EXCEPTION
  WHEN OTHERS THEN
    ROLLBACK;
    RAISE;
END;
